<?php declare(strict_types=1);namespace App\Interface\Http\Arena\Controller;use App\Application\Arena\Service\AnswerDuelService;use App\Application\Identity\Service\AuthService;use App\Infrastructure\Http\ApiResponseFactory;use App\Interface\Http\Identity\IdentityRequestFactory;use Psr\Http\Message\ResponseInterface;use Psr\Http\Message\ServerRequestInterface;final class ArenaAnswerController{public function __construct(private readonly AuthService $auth,private readonly AnswerDuelService $service,private readonly ApiResponseFactory $responses){}public function answer(ServerRequestInterface $r,ResponseInterface $s,string $id,string $optionId):ResponseInterface{try{$user=$this->auth->currentUser((new IdentityRequestFactory())->accessToken($r));$accepted=$this->service->answer($id,$user->id,$optionId);return$this->responses->success($s,['accepted'=>$accepted],(string)$r->getAttribute('request_id'));}catch(\Throwable){return$this->responses->problem($s,'STATE_CONFLICT','A resposta não pode ser aceita.',409,(string)$r->getAttribute('request_id'));}}}
